package com.cryptostrategy.platform.evaluation.internal;import static org.junit.jupiter.api.Assertions.*;import com.cryptostrategy.platform.backtesting.api.model.*;import com.cryptostrategy.platform.evaluation.api.model.*;import com.cryptostrategy.platform.experiment.api.*;import com.cryptostrategy.platform.experiment.api.job.*;import java.math.BigDecimal;import java.time.Instant;import java.util.*;import org.junit.jupiter.api.Test;
class DeterministicEvaluatorTest{@Test void calculatesFourMetricsAndEligibility(){BacktestResult result=result(5);EvaluationResult evaluation=new DeterministicEvaluator().evaluate(result,new MetricVersion("metrics-v1"),new RankingVersion("ranking-v1"));assertEquals(5,evaluation.numberOfTrades());assertTrue(evaluation.leaderboardEligible());assertEquals(new BigDecimal("0.2000000000"),evaluation.maximumDrawdown());assertTrue(evaluation.overallScore().compareTo(BigDecimal.ZERO)>=0);}@Test void zeroTradesIsFiniteAndIneligible(){var e=new DeterministicEvaluator().evaluate(result(0),new MetricVersion("metrics-v1"),new RankingVersion("ranking-v1"));assertEquals(new BigDecimal("0E-10"),e.winRate());assertFalse(e.leaderboardEligible());}
 @Test void frozenResultReproducesMetricsAndFingerprint(){var evaluator=new DeterministicEvaluator();var source=result(5);var a=evaluator.evaluate(source,new MetricVersion("metrics-v1"),new RankingVersion("ranking-v1"));var b=evaluator.evaluate(source,new MetricVersion("metrics-v1"),new RankingVersion("ranking-v1"));assertTrue(new EvaluationReproductionVerifier().verify(a,b).matched());var changed=evaluator.evaluate(source,new MetricVersion("metrics-v2"),new RankingVersion("ranking-v1"));assertFalse(new EvaluationReproductionVerifier().verify(a,changed).matched());}
 private BacktestResult result(int count){BacktestResultId id=new BacktestResultId("00000000000000000000000010");List<Trade> trades=new ArrayList<>();for(int i=0;i<count;i++)trades.add(new Trade(new TradeId(String.format("000000000000000000000000%02d",11+i)),id,i,PositionSide.LONG,Instant.parse("2026-01-01T00:00:00Z").plusSeconds(i*120L),Instant.parse("2026-01-01T00:01:00Z").plusSeconds(i*120L),Money.of(BigDecimal.TEN),Money.of(BigDecimal.valueOf(11)),new Quantity(BigDecimal.ONE),Money.zero(),Money.zero(),Money.zero(),BigDecimal.ONE,Money.of(BigDecimal.valueOf(1001+i)),ExitReason.STRATEGY_SELL));return new BacktestResult(id,new ExperimentId("00000000000000000000000020"),new CandidateId("00000000000000000000000021"),new JobId("00000000000000000000000022"),new AttemptId("00000000000000000000000023"),new BacktestProvenance("m","d","s"),BacktestAssumptions.mvp(BigDecimal.valueOf(1000),BigDecimal.ZERO,BigDecimal.ZERO),Money.of(BigDecimal.valueOf(1000)),Money.of(BigDecimal.valueOf(1100)),Money.zero(),trades,new EquityCurveSummary(2,Money.of(BigDecimal.valueOf(1000)),Money.of(BigDecimal.valueOf(800)),0,1,"sha256:"+"0".repeat(64)),"sha256:"+"1".repeat(64),Instant.parse("2026-01-01T01:00:00Z"));}}
